\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential
\usetikzlibrary{patterns,intersections,backgrounds,arrows.meta,decorations.markings,calc}

\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	tick style={draw=black,thick},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
	%grid = both,
	xmin = -1,
	xmax = 2,
	ymin = -1.5,
	ymax = 1.5,
	xtick = {10},
	%xticklabels={$1/e$,$e$},
	ytick = {-1,1}, 
	%yticklabels={$1/e$,$e$},
	x tick label style={xshift={(\tick==-2)*-8pt}},
%	x tick label style={xshift={(\tick==-2)*-8pt}},
%	y tick label style={yshift={(\tick==3)*6pt}},
%	y tick label style={yshift={(\tick==-3)*-6pt}},
	xlabel = {$x$},
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
	at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

% Fill	
\draw[draw=none,fill=lightblue, fill opacity=0.3]
	plot[variable=\x, domain={-1}:{1}, samples=100,orangepeel] (axis cs:{(\x)^4},{(\x)^3}) --
	plot[variable=\x, domain={-1}:{1}, samples=100,fadedpink] (axis cs:{1},{-\x}); 

% C_1
\draw[very thick,color=orangepeel]
	plot[variable=\x, domain={-1}:{1}, samples=100,orangepeel] (axis cs:{(\x)^4},{(\x)^3});

% C_2
\draw[very thick,color=fadedpink]
	plot[variable=\x, domain={-1}:{1}, samples=100,fadedpink] (axis cs:{1},{-\x});

% Arrows	
\draw[draw=none,mark=none,
		postaction={decorate,
			decoration={
					markings,
						mark=at position 0.15 with {\arrow[fill opacity=1,>=stealth, black, very thick]{>};},
						mark=at position 0.45 with {\arrow[fill opacity=1,>=stealth, black, very thick]{>};},
						mark=at position 0.9 with {\arrow[fill opacity=1,>=stealth, black, very thick]{>};},
						mark=at position 0.7 with {\arrow[fill opacity=1,>=stealth, black, very thick]{>};},
					}}]
	plot[variable=\x, domain={-1}:{1}, samples=200,orangepeel] (axis cs:{(\x)^4},{(\x)^3}) --
	plot[variable=\x, domain={-1}:{1}, samples=200,fadedpink] (axis cs:{1},{-\x});


\node[deepskyblue] at (axis cs: 0.7,-0.4) {$D$};
\node[orangepeel] at (axis cs: 0.5,-0.8) {$C_1$};
\node[fadedpink] at (axis cs: 1.2,-0.5) {$C_2$};
\node at (axis cs: 1.1,-0.15) {\footnotesize $1$};

	\end{axis}
\end{tikzpicture}
\end{document}
